def investigate(context, acquire):
    history = acquire("history")
    receipts = []
    for r in history:
        if isinstance(r, dict) and "actions" in r and "observed" in r:
            receipts.append(r)

    def norm_actions(actions):
        out = []
        for a in actions:
            if not isinstance(a, dict):
                continue
            op = a.get("op")
            conn = a.get("connection", "main")
            if conn not in ("main", "other"):
                conn = "main"
            key = a.get("key")
            val = a.get("value")
            out.append((op, conn, key, val))
        return out

    def simulate(actions, put_mode, trig, channel_mode):
        # committed state
        committed = {}
        # per-connection transaction state
        in_tx = {"main": False, "other": False}
        # per-connection pending writes: list of (op,key,val)
        pending = {"main": [], "other": []}
        # counters
        changes = {"main": 0, "other": 0}
        total = {"main": 0, "other": 0}

        def apply_write(conn, op, key, val):
            # returns number of direct row changes for this statement
            if op == "put":
                if put_mode == "ignore":
                    if key in committed:
                        return 0
                    committed[key] = val
                    return 1
                elif put_mode == "replace":
                    committed[key] = val
                    return 1
                else:  # upsert
                    committed[key] = val
                    return 1
            elif op == "update":
                if key in committed:
                    committed[key] = val
                    return 1
                return 0
            elif op == "delete":
                if key in committed:
                    del committed[key]
                    return 1
                return 0
            return 0

        def trigger_count(op, key, val, direct):
            if trig == "none":
                return 0
            # AFTER INSERT trigger inserts one row into log
            if op == "put":
                # trigger fires on actual insert
                if put_mode == "ignore":
                    if direct == 1:
                        return 1
                    return 0
                elif put_mode == "replace":
                    # REPLACE deletes then inserts; trigger fires on insert
                    return 1
                else:
                    # upsert: insert or update; trigger only on insert
                    # if key existed before, it's update -> no trigger
                    # we need to know if it was insert
                    # direct==1 always, but trigger only if new row
                    # approximate: if key was absent before
                    return 1 if direct == 1 and key not in committed_before else 0
            return 0

        # We need committed_before for trigger logic; restructure
        # Simpler: track whether put inserted a new row
        def apply_write2(conn, op, key, val):
            nonlocal_committed = committed
            if op == "put":
                existed = key in committed
                if put_mode == "ignore":
                    if existed:
                        return 0, 0
                    committed[key] = val
                    return 1, 1  # direct, trigger
                elif put_mode == "replace":
                    committed[key] = val
                    return 1, 1
                else:  # upsert
                    committed[key] = val
                    if existed:
                        return 1, 0
                    return 1, 1
            elif op == "update":
                if key in committed:
                    committed[key] = val
                    return 1, 0
                return 0, 0
            elif op == "delete":
                if key in committed:
                    del committed[key]
                    return 1, 0
                return 0, 0
            return 0, 0

        for (op, conn, key, val) in actions:
            if op == "begin":
                in_tx[conn] = True
                pending[conn] = []
            elif op == "commit":
                for (wop, wkey, wval) in pending[conn]:
                    d, t = apply_write2(conn, wop, wkey, wval)
                    changes[conn] += d
                    total[conn] += d + t
                pending[conn] = []
                in_tx[conn] = False
            elif op == "rollback":
                pending[conn] = []
                in_tx[conn] = False
            elif op in ("put", "update", "delete"):
                if in_tx[conn]:
                    pending[conn].append((op, key, val))
                else:
                    d, t = apply_write2(conn, op, key, val)
                    changes[conn] += d
                    total[conn] += d + t

        if channel_mode == "changes":
            return changes["main"]
        elif channel_mode == "total_main":
            return total["main"]
        else:
            return total["main"] + total["other"]

    # Enumerate family members
    put_modes = ["ignore", "replace", "upsert"]
    trigs = ["none", "insert"]
    channel_modes = ["changes", "total_main", "total_both"]

    candidates = []
    for pm in put_modes:
        for tg in trigs:
            for cm in channel_modes:
                candidates.append((pm, tg, cm))

    # Filter candidates by receipts
    def check_receipt(cand, r):
        pm, tg, cm = cand
        acts = norm_actions(r["actions"])
        obs = r["observed"]
        # simulate committed state
        committed = {}
        in_tx = {"main": False, "other": False}
        pending = {"main": [], "other": []}
        changes = {"main": 0, "other": 0}
        total = {"main": 0, "other": 0}

        def apply_write2(conn, op, key, val):
            if op == "put":
                existed = key in committed
                if pm == "ignore":
                    if existed:
                        return 0, 0
                    committed[key] = val
                    return 1, 1
                elif pm == "replace":
                    committed[key] = val
                    return 1, 1
                else:
                    committed[key] = val
                    if existed:
                        return 1, 0
                    return 1, 1
            elif op == "update":
                if key in committed:
                    committed[key] = val
                    return 1, 0
                return 0, 0
            elif op == "delete":
                if key in committed:
                    del committed[key]
                    return 1, 0
                return 0, 0
            return 0, 0

        for (op, conn, key, val) in acts:
            if op == "begin":
                in_tx[conn] = True
                pending[conn] = []
            elif op == "commit":
                for (wop, wkey, wval) in pending[conn]:
                    d, t = apply_write2(conn, wop, wkey, wval)
                    changes[conn] += d
                    total[conn] += d + t
                pending[conn] = []
                in_tx[conn] = False
            elif op == "rollback":
                pending[conn] = []
                in_tx[conn] = False
            elif op in ("put", "update", "delete"):
                if in_tx[conn]:
                    pending[conn].append((op, key, val))
                else:
                    d, t = apply_write2(conn, op, key, val)
                    changes[conn] += d
                    total[conn] += d + t

        if cm == "changes":
            ch = changes["main"]
        elif cm == "total_main":
            ch = total["main"]
        else:
            ch = total["main"] + total["other"]

        cnt = len(committed)
        sm = sum(committed.values())

        if obs.get("channel") != ch:
            return False
        if obs.get("committed_count") != cnt:
            return False
        if obs.get("committed_sum") != sm:
            return False
        return True

    for r in receipts:
        candidates = [c for c in candidates if check_receipt(c, r)]

    goal = context.get("goal")
    actions = norm_actions(context.get("actions", []))

    if not candidates:
        return {"value": None, "unresolved": True}

    results = set()
    for cand in candidates:
        pm, tg, cm = cand
        # simulate
        committed = {}
        in_tx = {"main": False, "other": False}
        pending = {"main": [], "other": []}
        changes = {"main": 0, "other": 0}
        total = {"main": 0, "other": 0}

        def apply_write2(conn, op, key, val):
            if op == "put":
                existed = key in committed
                if pm == "ignore":
                    if existed:
                        return 0, 0
                    committed[key] = val
                    return 1, 1
                elif pm == "replace":
                    committed[key] = val
                    return 1, 1
                else:
                    committed[key] = val
                    if existed:
                        return 1, 0
                    return 1, 1
            elif op == "update":
                if key in committed:
                    committed[key] = val
                    return 1, 0
                return 0, 0
            elif op == "delete":
                if key in committed:
                    del committed[key]
                    return 1, 0
                return 0, 0
            return 0, 0

        for (op, conn, key, val) in actions:
            if op == "begin":
                in_tx[conn] = True
                pending[conn] = []
            elif op == "commit":
                for (wop, wkey, wval) in pending[conn]:
                    d, t = apply_write2(conn, wop, wkey, wval)
                    changes[conn] += d
                    total[conn] += d + t
                pending[conn] = []
                in_tx[conn] = False
            elif op == "rollback":
                pending[conn] = []
                in_tx[conn] = False
            elif op in ("put", "update", "delete"):
                if in_tx[conn]:
                    pending[conn].append((op, key, val))
                else:
                    d, t = apply_write2(conn, op, key, val)
                    changes[conn] += d
                    total[conn] += d + t

        if goal == "channel":
            if cm == "changes":
                v = changes["main"]
            elif cm == "total_main":
                v = total["main"]
            else:
                v = total["main"] + total["other"]
        elif goal == "committed_count":
            v = len(committed)
        elif goal == "committed_sum":
            v = sum(committed.values())
        else:
            return {"value": None, "unresolved": True}
        results.add(v)

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
